import path from 'node:path';

export interface Config {
  port: number;
  host: string;
  claudeboxUrl: string;
  claudeboxApiKey: string;
  /** Hostname used to reach preview ports (defaults to CLAUDEBOX_URL's hostname). */
  previewHost: string;
  whisperUrl: string;
  projectsDir: string;
  uploadsDir: string;
  dbPath: string;
  sessionSecret: string;
  adminEmail: string | null;
  adminPassword: string | null;
  adminName: string;
  trustProxy: string[];
  publicUrl: string;
  secureCookies: boolean;
  webDist: string;
  /** Paths as seen inside claudebox (attachments are passed using these). */
  claudeboxUploadsDir: string;
  claudeboxProjectsDir: string;
  logLevel: string;
  previewPortMin: number;
  previewPortMax: number;
}

function env(name: string, def?: string): string {
  const v = process.env[name];
  if (v === undefined || v === '') {
    if (def === undefined) throw new Error(`Missing required env var ${name}`);
    return def;
  }
  return v;
}

export function loadConfig(overrides: Partial<Config> = {}): Config {
  const claudeboxUrl = env('CLAUDEBOX_URL', 'http://claudebox:3000').replace(/\/+$/, '');
  const publicUrl = env('PUBLIC_URL', 'http://localhost:8080').replace(/\/+$/, '');
  let sessionSecret = process.env.SESSION_SECRET || '';
  if (!sessionSecret) {
    // Dev fallback only; production must set SESSION_SECRET (sessions are invalidated on restart otherwise).
    sessionSecret = 'dev-insecure-session-secret';
    if (process.env.NODE_ENV === 'production') throw new Error('SESSION_SECRET is required in production');
  }
  const cfg: Config = {
    port: Number(env('PORT', '8080')),
    host: env('HOST', '0.0.0.0'),
    claudeboxUrl,
    claudeboxApiKey: env('CLAUDEBOX_API_KEY', ''),
    previewHost: env('PREVIEW_HOST', new URL(claudeboxUrl).hostname),
    whisperUrl: env('WHISPER_URL', 'http://whisper:9000').replace(/\/+$/, ''),
    projectsDir: path.resolve(env('PROJECTS_DIR', '/data/projects')),
    uploadsDir: path.resolve(env('UPLOADS_DIR', '/data/uploads')),
    dbPath: path.resolve(env('DB_PATH', '/data/db/nxeon.db')),
    sessionSecret,
    adminEmail: process.env.ADMIN_EMAIL || null,
    adminPassword: process.env.ADMIN_PASSWORD || null,
    adminName: env('ADMIN_NAME', 'Admin'),
    // Default: loopback + docker bridge ranges (Caddy on the host reaches the container via the bridge gateway).
    trustProxy: env('TRUST_PROXY', '127.0.0.1/8,::1/128,172.16.0.0/12')
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean),
    publicUrl,
    secureCookies: publicUrl.startsWith('https://'),
    webDist: path.resolve(env('WEB_DIST', path.resolve(process.cwd(), '../web/dist'))),
    claudeboxUploadsDir: env('CLAUDEBOX_UPLOADS_DIR', '/workspace/uploads'),
    claudeboxProjectsDir: env('CLAUDEBOX_PROJECTS_DIR', '/workspace/projects'),
    logLevel: env('LOG_LEVEL', 'info'),
    previewPortMin: Number(env('PREVIEW_PORT_MIN', '4100')),
    previewPortMax: Number(env('PREVIEW_PORT_MAX', '4199')),
  };
  return { ...cfg, ...overrides };
}
