cat > /opt/nxeon-workspace/deploy/Caddyfile.workspace <<'EOF'
# Nxeon Workspace — final Caddy site block (staged; the coordinator installs it).
#
# Replaces the placeholder `workspace.trynxeon.com { ... basic_auth ... file_server }`
# block in /etc/caddy/Caddyfile. App auth replaces basic_auth.
#
#   sudo cp /etc/caddy/Caddyfile /etc/caddy/Caddyfile.bak.$(date +%s)
#   (replace the workspace.trynxeon.com block with this file's contents, or
#    `import /opt/nxeon-workspace/deploy/Caddyfile.workspace` from the main Caddyfile)
#   sudo caddy validate --adapter caddyfile --config /etc/caddy/Caddyfile
#   sudo systemctl reload caddy

workspace.trynxeon.com {
	# Compress text responses. Never compress event streams (keeps SSE unbuffered).
	encode {
		zstd
		gzip
		match {
			header Content-Type text/html*
			header Content-Type text/css*
			header Content-Type text/plain*
			header Content-Type text/javascript*
			header Content-Type application/javascript*
			header Content-Type application/json*
			header Content-Type application/wasm*
			header Content-Type image/svg+xml*
		}
	}

	# Uploads are capped at 50 MB/file by the app; allow multipart overhead.
	request_body {
		max_size 60MB
	}

	header {
		Strict-Transport-Security "max-age=31536000"
		X-Content-Type-Options nosniff
		Referrer-Policy strict-origin-when-cross-origin
		# The preview iframe (/preview/<slug>/) is same-origin: do NOT send
		# X-Frame-Options DENY. The app sets CSP `frame-ancestors 'self'`;
		# SAMEORIGIN is only added when the upstream did not set its own.
		?X-Frame-Options SAMEORIGIN
		-Server
		-X-Powered-By
	}

	reverse_proxy 127.0.0.1:8080 {
		# Stream immediately (SSE, chunked downloads, long-poll). WebSockets
		# (/ws, preview HMR) are proxied transparently by Caddy.
		flush_interval -1
		# Caddy overwrites X-Forwarded-For with the real client IP (incoming
		# XFF from clients is not trusted because no trusted_proxies are set).
		header_up X-Real-IP {remote_host}
		transport http {
			dial_timeout 5s
			response_header_timeout 0
		}
	}

	log {
		output file /var/log/caddy/workspace.log {
			roll_size 50MiB
			roll_keep 10
			roll_keep_for 720h
		}
		format json
	}
}
EOF
